E=[('Redline 7 · counterfeits of love, not counterfeit sons', 89, 'Jesus shows us one of them in the story itself; the other is the father this father refused to be.', 'Jesus shows us one of them in the story itself, in the elder brother; the other is the love this father refused to give.'), ('Redline 7 · counterfeits of love, not counterfeit sons', 93, 'The second counterfeit is the *elder brother.*', 'The second counterfeit is the one Jesus shows us in the *elder brother.*'), ('Redline 7 · counterfeits of love, not counterfeit sons', 98, 'in a world that knows only the two counterfeits.', 'in a world that knows only two counterfeits of love.'), ('Redline 7 · counterfeits of love, not counterfeit sons', 101, 'will I be the father, or one of the counterfeits?*', 'will I love like the father, or fall into one of the counterfeits?*'), ('Redline 7 · counterfeits of love, not counterfeit sons', 162, 'or the elder brother at the door.', "or the elder brother's closed door."), ('Redline 7 · counterfeits of love, not counterfeit sons', 166, 'the difference between the father and the two counterfeits.', "the difference between the father's love and its two counterfeits."), ('Redline 7 · counterfeits of love, not counterfeit sons', 282, '*In the hardest moment of this day, was I the father — or one of the two counterfeits?*', '*In the hardest moment of this day, did I love like the father — or fall into one of the two counterfeits?*')]
